1	import { joinRequests } from "@paperclipai/db";
2	
3	type JoinRequestLike = Pick<
4	  typeof joinRequests.$inferSelect,
5	  | "id"
6	  | "requestType"
7	  | "status"
8	  | "requestingUserId"
9	  | "requestEmailSnapshot"
10	  | "createdAt"
11	  | "updatedAt"
12	>;
13	
14	function nonEmptyTrimmed(value: string | null | undefined): string | null {
15	  const trimmed = value?.trim();
16	  return trimmed ? trimmed : null;
17	}
18	
19	export function normalizeJoinRequestEmail(
20	  email: string | null | undefined
21	): string | null {
22	  const trimmed = nonEmptyTrimmed(email);
23	  return trimmed ? trimmed.toLowerCase() : null;
24	}
25	
26	export function humanJoinRequestIdentity(
27	  row: Pick<
28	    JoinRequestLike,
29	    "requestType" | "requestingUserId" | "requestEmailSnapshot"
30	  >
31	): string | null {
32	  if (row.requestType !== "human") return null;
33	  const requestingUserId = nonEmptyTrimmed(row.requestingUserId);
34	  if (requestingUserId) return `user:${requestingUserId}`;
35	  const email = normalizeJoinRequestEmail(row.requestEmailSnapshot);
36	  return email ? `email:${email}` : null;
37	}
38	
39	export function findReusableHumanJoinRequest<
40	  T extends Pick<
41	    JoinRequestLike,
42	    "id" | "requestType" | "status" | "requestingUserId" | "requestEmailSnapshot"
43	  >,
44	>(
45	  rows: T[],
46	  actor: { requestingUserId?: string | null; requestEmailSnapshot?: string | null }
47	): T | null {
48	  const actorUserId = nonEmptyTrimmed(actor.requestingUserId);
49	  if (actorUserId) {
50	    const sameUser = rows.find(
51	      (row) =>
52	        row.requestType === "human" &&
53	        (row.status === "pending_approval" || row.status === "approved") &&
54	        row.requestingUserId === actorUserId
55	    );
56	    if (sameUser) return sameUser;
57	  }
58	
59	  const actorEmail = normalizeJoinRequestEmail(actor.requestEmailSnapshot);
60	  if (!actorEmail) return null;
61	  return (
62	    rows.find(
63	      (row) =>
64	        row.requestType === "human" &&
65	        (row.status === "pending_approval" || row.status === "approved") &&
66	        normalizeJoinRequestEmail(row.requestEmailSnapshot) === actorEmail
67	    ) ?? null
68	  );
69	}
70	
71	export function collapseDuplicatePendingHumanJoinRequests<
72	  T extends Pick<
73	    JoinRequestLike,
74	    "id" | "requestType" | "status" | "requestingUserId" | "requestEmailSnapshot"
75	  >,
76	>(rows: T[]): T[] {
77	  const seen = new Set<string>();
78	  return rows.filter((row) => {
79	    if (row.requestType !== "human" || row.status !== "pending_approval") {
80	      return true;
81	    }
82	    const identity = humanJoinRequestIdentity(row);
83	    if (!identity) return true;
84	    if (seen.has(identity)) return false;
85	    seen.add(identity);
86	    return true;
87	  });
88	}
